try{require_admin();if($_SERVER['REQUEST_METHOD']!=='POST')throw new RuntimeException('POST required.');if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_SERVER['HTTP_X_CSRF_TOKEN']??'')))throw new RuntimeException('Security token expired.');$last=(int)($_SESSION['ai_ticket_suggestion_at']??0);if(time()-$last<8)throw new RuntimeException('Wait a few seconds before generating another suggestion.');$body=json_decode((string)file_get_contents('php://input'),true)?:[];$ticketId=(int)($body['ticket_id']??0);$q=db()->prepare('SELECT t.*,u.name customer_name,u.email FROM support_tickets t JOIN users u ON u.id=t.user_id WHERE t.id=?');$q->execute([$ticketId]);$ticket=$q->fetch();if(!$ticket)throw new RuntimeException('Ticket not found.');$q=db()->prepare('SELECT m.message,m.is_staff,m.is_internal,m.created_at,u.name FROM support_messages m LEFT JOIN users u ON u.id=m.user_id WHERE m.ticket_id=? ORDER BY m.id DESC LIMIT 12');$q->execute([$ticketId]);$messages=array_reverse($q->fetchAll());$_SESSION['ai_ticket_suggestion_at']=time();echo json_encode(['ok'=>true,'suggestion'=>openai_ticket_suggestion($ticket,$messages)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}catch(Throwable $e){http_response_code(422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}
